//#region src/packs/templates.ts
function buildTemplate(line, name, nodes, links) {
	const graph = {
		version: 1,
		name,
		line,
		nodes: [],
		edges: []
	};
	for (const spec of nodes) graph.nodes.push({
		id: spec.id,
		type: spec.type,
		x: spec.x,
		y: spec.y,
		...spec.title ? { title: spec.title } : {},
		config: spec.config ?? {}
	});
	for (const [fromNode, fromPort, toNode, toPort] of links) graph.edges.push({
		from: {
			node: fromNode,
			port: fromPort
		},
		to: {
			node: toNode,
			port: toPort
		}
	});
	return graph;
}
