/** 判定一条新闻是否与技术主题无关；返回 true 表示丢弃。 */
function isOffTopicNews(input) {
	if (NEWS_TRUSTED_SOURCE_KEYS.includes(input.sourceKey)) return false;
	const text = `${input.title}\n${input.summary}\n${input.aiSummary ?? ""}`;
	if (NEWS_OFF_TOPIC_PATTERNS.some((re) => re.test(text))) return true;
	return !NEWS_TECH_TERMS.some((re) => re.test(text));
}
/** heat_kind 白名单。空串＝这源不给热度。points 是 HN 的分数，star-velocity 是 GitHub 的日增星数。 */
const NEWS_HEAT_KINDS = [
	"",
	"points",
	"star-velocity"
];
/** 解析 YYYY-MM-DD / YYYY-MM-DD HH:mm / ISO 日期；解析不出返回 null。 */
function parseNewsDate(text) {
	const m = text.match(/^(\d{4})-(\d{2})-(\d{2})/);
	if (!m) return null;
	const t = Date.parse(`${m[1]}-${m[2]}-${m[3]}T00:00:00`);
	return Number.isFinite(t) ? t : null;
}
/**
* 规范化 URL，用于判断「是不是同一个链接」（事件合并用）。
*
* 只做**确定性的**几件事：去 utm_* / fbclid / gclid 这类跟踪参数、去 ref/from 这类来源参数、
* 去尾部斜杠、去 `www.`、统一小写、丢掉 #fragment。
* **不做**模糊匹配（标题相似度、域名别名、短链展开）：那种误合并比留两条重复更难收拾。
*/
const NEWS_TRACKING_PARAMS = /^(utm_|fbclid$|gclid$|mc_cid$|mc_eid$|ref$|referrer$|source$|from$|spm$|share_)/i;
function normalizeNewsUrl(raw) {
	let parsed;
	try {
		parsed = new URL(str(raw));
	} catch {
		return str(raw).trim().toLowerCase();
	}
	return normalizeParsedUrl(parsed);
}
function normalizeParsedUrl(parsed) {
	const host = parsed.hostname.toLowerCase().replace(/^www\./, "");
	const params = Array.from(parsed.searchParams.entries()).filter(([key]) => !NEWS_TRACKING_PARAMS.test(key)).sort(([a], [b]) => a.localeCompare(b));
	const search = params.length === 0 ? "" : `?${params.map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(v)}`).join("&")}`;
	const path = parsed.pathname.replace(/\/+$/, "");
	return `${host}${parsed.port === "" ? "" : `:${parsed.port}`}${path}${search}`;
}
/**
* 事件键：同一规范化 URL 归一成同一个短串，用来把「官方博客 + HN 讨论」合并成一张卡。
* 只用 URL 一个信号，所以两条必然指向同一个页面——这是合并唯一不会出错的情形。
*/
function newsEventKey(raw) {
	const normalized = normalizeNewsUrl(raw);
	if (normalized === "") return "";
	return `ev-${createHash("sha256").update(normalized).digest("hex").slice(0, 16)}`;
}
/**
* 校验 + 归类 + 新鲜度闸门 + 相关性闸门。
* 模型吐的内容一概不可信，这里做确定性兜底：URL 合法性、枚举白名单、时间过旧/未来、主题是否对题。
*/
function cleanNewsItemsDetailed(value) {
	const items = [];
	const dropped = {
		badUrl: 0,
		stale: 0,
		future: 0,
		offTopic: 0
	};
	const now = Date.now();
	for (const raw of list(value).slice(0, 20)) {
		const title = str(raw?.title).trim().slice(0, 300);
		const urlText = str(raw?.url).trim();
		if (title === "" || urlText === "") continue;
		let url = "";
		try {
			const parsed = new URL(urlText);
			if (parsed.protocol === "http:" || parsed.protocol === "https:") url = parsed.toString().slice(0, 2e3);
		} catch {}
		if (url === "") {
			dropped.badUrl += 1;
			continue;
		}
		const kind = normalizeNewsKind(raw?.kind);
		const publishedAt = str(raw?.publishedAt).trim().slice(0, 40);
		const stamp = parseNewsDate(publishedAt);
		if (stamp !== null) {
			const ageDays = (now - stamp) / 864e5;
			if (ageDays < -1) {
				dropped.future += 1;
				continue;
			}
			if (ageDays > (NEWS_EVERGREEN_KINDS.includes(kind) ? NEWS_MAX_AGE_DAYS_EVERGREEN : NEWS_MAX_AGE_DAYS)) {
				dropped.stale += 1;
				continue;
			}
		}
		const sourceKeyRaw = str(raw?.sourceKey).trim().toLowerCase();
		const sourceKey = NEWS_SOURCE_KEYS.includes(sourceKeyRaw) ? sourceKeyRaw : "";
		const source = str(raw?.source).trim().slice(0, 120);
		const summary = str(raw?.summary).trim().slice(0, 600);
		const aiSummary = str(raw?.aiSummary).trim().slice(0, 1600);
		if (isOffTopicNews({
			title,
			summary,
			aiSummary,
			sourceKey
		})) {
			dropped.offTopic += 1;
			continue;
		}
		const titleZh = str(raw?.titleZh).trim().slice(0, 300);
		const summaryZh = str(raw?.summaryZh).trim().slice(0, 600);
		const hash = createHash("sha256").update(url.toLowerCase()).digest("hex").slice(0, 32);
		const heatRaw = Number(raw?.heat ?? 0);
		const heat = Number.isFinite(heatRaw) && heatRaw > 0 ? Math.round(heatRaw * 100) / 100 : 0;
		const heatKindRaw = str(raw?.heatKind).trim().toLowerCase();
		const heatKind = heat > 0 && NEWS_HEAT_KINDS.includes(heatKindRaw) && heatKindRaw !== "" ? heatKindRaw : "";
		items.push({
			title,
			url,
			source,
			sourceKey,
			kind,
			publishedAt,
			summary,
			aiSummary,
			titleZh,
			summaryZh,
			heat,
			heatKind,
			eventKey: newsEventKey(url),
			hash
		});
		if (items.length >= 20) break;
	}
	return {
		items,
		dropped
	};
}
function normalizeExportDir(raw) {
	let dir = str(raw).trim();
	if (dir === "" || dir === "~") dir = homedir();
	else if (dir.startsWith("~/")) dir = join(homedir(), dir.slice(2));
	if (!isAbsolute(dir)) dir = resolve(homedir(), dir);
	dir = resolve(dir);
	try {
		mkdirSync(dir, { recursive: true });
		if (!statSync(dir).isDirectory()) throw new Error("不是目录");
		accessSync(dir, constants.W_OK);
	} catch (cause) {
		throw new Error(`保存目录不可写：${dir}（${String(cause?.message ?? cause)}）`);
	}
	return dir;
}
function sanitizeFilename(raw) {
	const cleaned = str(raw).replace(/[\\/:*?"<>|\u0000-\u001f]/g, " ").replace(/\s+/g, " ").trim().slice(0, 70);
	return cleaned === "" ? "未命名笔记" : cleaned;
}
function uniqueExportPath(dir, base, ext) {
	let path = join(dir, `${base}${ext}`);
	let i = 2;
	while (existsSync(path)) {
		path = join(dir, `${base} (${i})${ext}`);
		i += 1;
	}
	return path;
}
/** 工作区路径校验：非空时必须是存在且可写的绝对路径（防止 .dsh-workbench 写进 DSH 进程 cwd）。 */
function normalizeWorkspacePath(raw) {
	const path = str(raw).trim();
	if (path === "") return "";
	if (!isAbsolute(path)) throw new Error(`工作区路径必须是绝对路径：${path}`);
	const resolved = resolve(path);
	if (!existsSync(resolved)) throw new Error(`工作区路径不存在：${resolved}`);
	try {
		if (!statSync(resolved).isDirectory()) throw new Error("不是目录");
		accessSync(resolved, constants.W_OK);
	} catch (cause) {
		throw new Error(`工作区路径不可用：${resolved}（${String(cause?.message ?? cause)}）`);
	}
	return resolved;
}
/** 追加式验证记录：保留历史，每条带时间戳。 */
function appendVerification(previous, addition) {
	const prev = str(previous).trimEnd();
	const add = str(addition).trim();
	if (add === "") return prev;
	if (prev === "") return `[${isoDateTimeSeconds()}]\n${add}`;
	return `${prev}\n\n[${isoDateTimeSeconds()}]\n${add}`;
}
function escapeHtmlHost(text) {
	return String(text).replace(/[&<>"']/g, (ch) => ({
		"&": "&amp;",
		"<": "&lt;",
		">": "&gt;",
		"\"": "&quot;",
		"'": "&#39;"
	})[ch] ?? ch);
}
