function cleanTags(value) {
	const out = [];
	for (const raw of list(value)) {
		const tag = str(raw).trim().replace(/^#/, "").slice(0, 24);
		if (tag !== "" && !out.includes(tag)) out.push(tag);
		if (out.length >= 20) break;
	}
	return out;
}
